  /**
   * @method
   * @name woo#createTrailingAmountOrder
   * @description create a trailing order by providing the symbol, type, side,
   * amount, price and trailingAmount
   * @see
   * https://developer.woox.io/api-reference/endpoint/trading/post_algo_order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much you want to trade in units of the base
   * currency, or number of contracts
   * @param {float} [price] the price for the order to be filled at, in units of
   * the quote currency, ignored in market orders
   * @param {float} trailingAmount the quote amount to trail away from the
   * current market price
   * @param {float} trailingTriggerPrice the price to activate a trailing order,
   * default uses the price argument
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createTrailingAmountOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
                            ccxt::any amount, ccxt::any price = ccxt::any{},
                            ccxt::any trailingAmount = ccxt::any{},
                            ccxt::any trailingTriggerPrice = ccxt::any{},
                            ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(trailingAmount, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" createTrailingAmountOrder() requires "
                                       "a trailingAmount argument"))));
                 }
                 if (isTrue(isEqual(trailingTriggerPrice, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" createTrailingAmountOrder() requires "
                                       "a trailingTriggerPrice argument"))));
                 }
                 ::setValue(params, std::string("trailingAmount"),
                            trailingAmount);
                 ::setValue(params, std::string("trailingTriggerPrice"),
                            trailingTriggerPrice);
                 return awaitValue(this->createOrder(symbol, type, side, amount,
                                                     price, params));
               })
        .share();
  }

