  /**
   * @method
   * @name woo#fetchMyTrades
   * @description fetch all trades made by the user
   * @see
   * https://developer.woox.io/api-reference/endpoint/trading/get_transactions
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.paginate] set to true if you want to fetch trades
   * with pagination
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallIncremental(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, std::string("page"), 500));
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 ccxt::any until = this->safeInteger(
                     params, std::string("until")); // unified in milliseconds
                 params = this->omit(params, ccxt::list{std::string("until")});
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("endTime"), until);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response =
                     awaitValue(this->v3PrivateGetTradeTransactionHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "success": true,
                 //         "data": {
                 //             "rows": [
                 //                 {
                 //                     "id": 1734947821,
                 //                     "symbol": "SPOT_LTC_USDT",
                 //                     "orderId": 60780383217,
                 //                     "executedPrice": 87.86,
                 //                     "executedQuantity": 0.1,
                 //                     "fee": 0.0001,
                 //                     "realizedPnl": null,
                 //                     "feeAsset": "LTC",
                 //                     "orderTag": "default",
                 //                     "side": "BUY",
                 //                     "executedTimestamp": "1752055173.630",
                 //                     "isMaker": 0
                 //                 }
                 //             ],
                 //             "meta": {
                 //                 "total": 1,
                 //                 "recordsPerPage": 100,
                 //                 "currentPage": 1
                 //             }
                 //         },
                 //         "timestamp": 1752055545121
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any trades =
                     this->safeList(data, std::string("rows"), ccxt::list{});
                 return this->parseTrades(trades, market, since, limit, params);
               })
        .share();
  }

