  /**
   * @method
   * @name woo#fetchFundingRate
   * @description fetch the current funding rate
   * @see
   * https://developer.woox.io/api-reference/endpoint/public_data/fundingRate
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<ccxt::any>
  fetchFundingRate(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = awaitValue(this->v3PublicGetFundingRate(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "success": true,
                 //         "data": {
                 //             "rows": [
                 //                 {
                 //                     "symbol": "PERP_BTC_USDT",
                 //                     "estFundingRate": "-0.00000441",
                 //                     "estFundingRateTimestamp":
                 //                     1751623979022, "lastFundingRate":
                 //                     "-0.00004953",
                 //                     "lastFundingRateTimestamp":
                 //                     1751616000000, "nextFundingTime":
                 //                     1751644800000,
                 //                     "lastFundingIntervalHours": 8,
                 //                     "estFundingIntervalHours": 8
                 //                 }
                 //             ]
                 //         },
                 //         "timestamp": 1751624037798
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rows =
                     this->safeList(data, std::string("rows"), ccxt::list{});
                 ccxt::any first = this->safeDict(rows, 0, ccxt::dict{});
                 return this->parseFundingRate(first, market);
               })
        .share();
  }

  /**
   * @method
   * @name woo#fetchFundingRates
   * @description fetch the funding rate for multiple markets
   * @see
   * https://developer.woox.io/api-reference/endpoint/public_data/fundingRate
   * @param {string[]|undefined} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rates-structure}, indexed by market
   * symbols
   */
  std::shared_future<ccxt::any>
  fetchFundingRates(ccxt::any symbols = ccxt::any{},
                    ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols);
                        ccxt::any response =
                            awaitValue(this->v3PublicGetFundingRate(params));
                        //
                        //     {
                        //         "success": true,
                        //         "data": {
                        //             "rows": [
                        //                 {
                        //                     "symbol": "PERP_BTC_USDT",
                        //                     "estFundingRate": "-0.00000441",
                        //                     "estFundingRateTimestamp":
                        //                     1751623979022, "lastFundingRate":
                        //                     "-0.00004953",
                        //                     "lastFundingRateTimestamp":
                        //                     1751616000000, "nextFundingTime":
                        //                     1751644800000,
                        //                     "lastFundingIntervalHours": 8,
                        //                     "estFundingIntervalHours": 8
                        //                 }
                        //             ]
                        //         },
                        //         "timestamp": 1751624037798
                        //     }
                        //
                        ccxt::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        ccxt::any rows = this->safeList(
                            data, std::string("rows"), ccxt::list{});
                        return this->parseFundingRates(rows, symbols);
                      })
        .share();
  }

  /**
   * @method
   * @name woo#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://developer.woox.io/api-reference/endpoint/public_data/fundingRateHistory
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding rate
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingRateHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallIncremental(
                       std::string("fetchFundingRateHistory"), symbol, since,
                       limit, params, std::string("page"), 25));
                 }
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 ccxt::any market = this->market(symbol);
                 symbol = ::getValue(market, std::string("symbol"));
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response =
                     awaitValue(this->v3PublicGetFundingRateHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "success": true,
                 //         "data": {
                 //             "rows": [
                 //                 {
                 //                     "symbol": "PERP_BTC_USDT",
                 //                     "fundingRate": "-0.00004953",
                 //                     "fundingRateTimestamp": 1751616000000,
                 //                     "nextFundingTime": 1751644800000,
                 //                     "markPrice": "108708"
                 //                 }
                 //             ],
                 //             "meta": {
                 //                 "total": 11690,
                 //                 "recordsPerPage": 25,
                 //                 "currentPage": 1
                 //             }
                 //         },
                 //         "timestamp": 1751632390031
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any rows =
                     this->safeList(data, std::string("rows"), ccxt::list{});
                 ccxt::any rates = ccxt::list{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(rows));
                      postFixIncrement(i)) {
                   ccxt::any entry = ::getValue(rows, i);
                   ccxt::any marketId =
                       this->safeString(entry, std::string("symbol"));
                   ccxt::any timestamp = this->safeInteger(
                       entry, std::string("fundingRateTimestamp"));
                   arrayPush(
                       rates,
                       ccxt::dict{
                           {std::string("info"), entry},
                           {std::string("symbol"), this->safeSymbol(marketId)},
                           {std::string("fundingRate"),
                            this->safeNumber(entry,
                                             std::string("fundingRate"))},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                       });
                 }
                 ccxt::any sorted =
                     this->sortBy(rates, std::string("timestamp"));
                 return this->filterBySymbolSinceLimit(sorted, symbol, since,
                                                       limit);
               })
        .share();
  }

