  /**
   * @method
   * @name woo#fetchLeverage
   * @description fetch the set leverage for a market
   * @see
   * https://developer.woox.io/api-reference/endpoint/account/get_account_info
   * @see https://developer.woox.io/api-reference/endpoint/futures/get_leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] *for swap markets only* 'cross' or
   * 'isolated'
   * @param {string} [params.positionMode] *for swap markets only* 'ONE_WAY' or
   * 'HEDGE_MODE'
   * @returns {object} a [leverage structure]{@link
   * https://docs.ccxt.com/?id=leverage-structure}
   */
  std::shared_future<ccxt::any>
  fetchLeverage(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   response = awaitValue(this->v3PrivateGetAccountInfo(params));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("swap")),
                                        true))) {
                   ccxt::any request = ccxt::dict{
                       {std::string("symbol"),
                        ::getValue(market, std::string("id"))},
                   };
                   ccxt::any marginMode = ccxt::any{};
                   ccxt::any marginModeparamsVariable =
                       this->handleMarginModeAndParams(
                           std::string("fetchLeverage"), params,
                           std::string("cross"));
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   ::setValue(request, std::string("marginMode"),
                              this->encodeMarginMode(marginMode));
                   response = awaitValue(this->v3PrivateGetFuturesLeverage(
                       this->extend(request, params)));
                 } else {
                   throw NotSupported(toString(add(
                       add(add(this->id,
                               std::string(
                                   " fetchLeverage() is not supported for ")),
                           ::getValue(market, std::string("type"))),
                       std::string(" markets"))));
                 }
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 return this->parseLeverage(data, market);
               })
        .share();
  }

  ccxt::any parseLeverage(ccxt::any leverage,
                          ccxt::any market = ccxt::any{}) override {
    ccxt::any marketId = this->safeString(leverage, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any marginMode =
        this->safeStringLower(leverage, std::string("marginMode"));
    ccxt::any spotLeverage =
        this->safeInteger(leverage, std::string("leverage"));
    if (isTrue(isEqual(spotLeverage, 0))) {
      spotLeverage = ccxt::any{};
    }
    ccxt::any longLeverage = spotLeverage;
    ccxt::any shortLeverage = spotLeverage;
    ccxt::any details =
        this->safeList(leverage, std::string("details"), ccxt::list{});
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(details));
         postFixIncrement(i)) {
      ccxt::any position = this->safeDict(details, i, ccxt::dict{});
      ccxt::any positionLeverage =
          this->safeInteger(position, std::string("leverage"));
      ccxt::any side = this->safeString(position, std::string("positionSide"));
      if (isTrue(isEqual(side, std::string("BOTH")))) {
        longLeverage = positionLeverage;
        shortLeverage = positionLeverage;
      } else if (isTrue(isEqual(side, std::string("LONG")))) {
        longLeverage = positionLeverage;
      } else if (isTrue(isEqual(side, std::string("SHORT")))) {
        shortLeverage = positionLeverage;
      }
    }
    return ccxt::dict{
        {std::string("info"), leverage},
        {std::string("symbol"), ::getValue(market, std::string("symbol"))},
        {std::string("marginMode"), marginMode},
        {std::string("longLeverage"), longLeverage},
        {std::string("shortLeverage"), shortLeverage},
    };
  }

  /**
   * @method
   * @name woo#setLeverage
   * @description set the level of leverage for a market
   * @see
   * https://developer.woox.io/api-reference/endpoint/spot_margin/set_leverage
   * @see https://developer.woox.io/api-reference/endpoint/futures/set_leverage
   * @param {float} leverage the rate of leverage (1, 2, 3, 4 or 5 for spot
   * markets, 1, 2, 3, 4, 5, 10, 15, 20 for swap markets)
   * @param {string} [symbol] unified market symbol (is mandatory for swap
   * markets)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] *for swap markets only* 'cross' or
   * 'isolated'
   * @param {string} [params.positionMode] *for swap markets only* 'ONE_WAY' or
   * 'HEDGE_MODE'
   * @returns {object} response from the exchange
   */
  std::shared_future<ccxt::any>
  setLeverage(ccxt::any leverage, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("leverage"), leverage},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 if (isTrue(isTrue((isEqual(symbol, ccxt::any{}))) ||
                            isTrue((isEqual(
                                this->safeBool(market, std::string("spot")),
                                true))))) {
                   return awaitValue(this->v3PrivatePostSpotMarginLeverage(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(
                                this->safeBool(market, std::string("swap")),
                                true))) {
                   ::setValue(request, std::string("symbol"),
                              this->safeString(market, std::string("id")));
                   ccxt::any marginMode = ccxt::any{};
                   ccxt::any marginModeparamsVariable =
                       this->handleMarginModeAndParams(
                           std::string("setLeverage"), params,
                           std::string("cross"));
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   ::setValue(request, std::string("marginMode"),
                              this->encodeMarginMode(marginMode));
                   return awaitValue(this->v3PrivatePutFuturesLeverage(
                       this->extend(request, params)));
                 } else {
                   throw NotSupported(toString(add(
                       add(add(this->id,
                               std::string(
                                   " fetchLeverage() is not supported for ")),
                           this->safeString(market, std::string("type"))),
                       std::string(" markets"))));
                 }
                 return ccxt::any{};
               })
        .share();
  }

